return items.map(item => {
  try {
    const llmResponse = $input.first().json.output;

    // Intentar parsear el JSON de la respuesta del LLM
    let jsonData;
    try {
      // Buscar JSON en la respuesta (por si hay texto adicional)
      const jsonMatch = llmResponse.match(/\{[\s\S]*\}/);
      if (jsonMatch) {
        jsonData = JSON.parse(jsonMatch[0]);
      } else {
        jsonData = JSON.parse(llmResponse);
      }
    } catch (parseError) {
      return {
        json: {
          error: 'Error al parsear JSON del LLM',
          originalResponse: llmResponse,
          parseError: parseError.message
        }
      };
    }

    // Validar que tenga la estructura básica
    if (!jsonData.intencion) {
      return {
        json: {
          error: 'JSON no contiene campo "intencion"',
          parsedData: jsonData
        }
      };
    }

    return {
      json: {
        parsedIntention: jsonData,
        originalMessage: $('Mapear mensaje').item.json.mensaje,
        remoteJid: $('Mapear mensaje').item.json.remoteJid
      }
    };
  } catch (error) {
    return {
      json: {
        error: 'Error general en parsing',
        errorMessage: error.message
      }
    };
  }
});

