try {
  // Obtener la respuesta del LLM
  const llmResponse = $input.item.json.output;

  // Limpiar caracteres de escape y parsear JSON
  const cleanedResponse = llmResponse
    .replace(/\\n/g, '')           // Remover \n
    .replace(/\\"/g, '"')          // Remover \" 
    .replace(/^"/, '')             // Remover comillas iniciales
    .replace(/"$/, '');            // Remover comillas finales

  // Parsear el JSON limpio
  const parsedData = JSON.parse(cleanedResponse);

  return {
    json: {
      parsedIntention: parsedData,
      success: true
    }
  };
} catch (error) {
  return {
    json: {
      error: 'Error al parsear JSON del LLM',
      originalResponse: $input.item.json.output,
      parseError: error.message,
      success: false
    }
  };
}

return items.map(item => {
  const originalMessage = item.json.message || '';

  // Eliminar comillas dobles del texto para evitar errores JSON
  const withoutQuotes = originalMessage.replace(/"/g, '');

  // Convertir el mensaje a un string JSON válido (escapa \n, etc.)
  const jsonSafeMessage = JSON.stringify(withoutQuotes);

  return {
    json: {
      ...item.json,
      message: jsonSafeMessage // ya es un string JSON escapado
    },
  };
});
